/// Tool to stop a running Incus instance
pub struct IncusStopInstanceTool;

#[async_trait]
impl Tool for IncusStopInstanceTool {
    fn name(&self) -> &str {
        "incus_stop_instance"
    }

    fn description(&self) -> &str {
        "Stop a running Incus instance. Use force=true for immediate stop."
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Instance name to stop"
                },
                "force": {
                    "type": "boolean",
                    "description": "Force stop immediately (default: false for graceful shutdown)"
                }
            },
            "required": ["name"]
        })
    }

    fn category(&self) -> &str {
        "containers"
    }

    fn tags(&self) -> Vec<String> {
        vec![
            "incus".into(),
            "containers".into(),
            "stop".into(),
            "write".into(),
        ]
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let name = input
            .get("name")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Missing required argument: name"))?;

        let force = input
            .get("force")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let args: Vec<&str> = if force {
            vec!["stop", name, "--force"]
        } else {
            vec!["stop", name]
        };

        let (stdout, stderr, success) = run_incus(&args).await?;
        if !success {
            return Err(anyhow::anyhow!(
                "incus stop {} failed: {}",
                name,
                stderr.trim()
            ));
        }

        Ok(json!({
