    }

    fn description(&self) -> &str {
        "Delete an Incus instance permanently. WARNING: Destroys the instance and its data. Use force=true to delete a running instance."
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Instance name to delete"
                },
                "force": {
                    "type": "boolean",
                    "description": "Force delete even if running (default: false)"
                }
            },
            "required": ["name"]
        })
    }

    fn category(&self) -> &str {
        "containers"
    }

    fn tags(&self) -> Vec<String> {
        vec![
            "incus".into(),
            "containers".into(),
            "delete".into(),
            "write".into(),
        ]
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let name = input
            .get("name")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Missing required argument: name"))?;

        let force = input
            .get("force")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let args: Vec<&str> = if force {
            vec!["delete", name, "--force"]
        } else {
            vec!["delete", name]
        };

        let (stdout, stderr, success) = run_incus(&args).await?;
        if !success {
            return Err(anyhow::anyhow!(
                "incus delete {} failed: {}",
                name,
                stderr.trim()
            ));
        }

        Ok(json!({
            "success": true,
            "name": name,
            "force": force,
            "output": stdout.trim(),
            "message": format!("Instance '{}' deleted successfully", name)
        }))
    }
}

