use anyhow::{anyhow, Result};
use async_trait::async_trait;
use simd_json::{json, prelude::*, OwnedValue as Value};
use std::{process::Command, sync::Arc};
use tracing::{error, info};

use crate::tool::{SecurityLevel, Tool};

pub struct IndexerSearchTool;

#[async_trait]
impl Tool for IndexerSearchTool {
    fn name(&self) -> &str {
        "indexer_search"
    }

    fn description(&self) -> &str {
        "Searches the OpenClaw code index semantically for relevant code snippets."
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": "The semantic query string to search for."
                },
                "repo": {
                    "type": "string",
                    "description": "Optional: Filter search results by repository name."
                },
                "language": {
                    "type": "string",
                    "description": "Optional: Filter search results by programming language."
                },
                "limit": {
                    "type": "number", // Assuming number for now, can be changed to integer if needed
                    "description": "Optional: Maximum number of results to return (default: 5)."
                }
            },
            "required": ["query"]
        })
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        info!("Executing openclaw_search with input: {:?}", input);

        let query = input.get("query").and_then(Value::as_str).ok_or_else(|| anyhow!("Missing 'query' argument"))?;

        let mut command = Command::new("bash");
        command.arg("openclaw-indexer/run.sh").arg("search").arg(query);

        if let Some(repo) = input.get("repo").and_then(Value::as_str) {
            command.arg("--repo").arg(repo);
        }
        if let Some(language) = input.get("language").and_then(Value::as_str) {
            command.arg("--language").arg(language);
        }
        if let Some(limit) = input.get("limit").and_then(Value::as_u64) {
            command.arg("--limit").arg(limit.to_string());
        }

        let output = command.output().map_err(|e| anyhow!("Failed to execute command: {}", e))?;

        if output.status.success() {
            let stdout = String::from_utf8_lossy(&output.stdout).to_string();
            info!("OpenClaw search successful.");

            let mut results = Vec::new();
            let mut current_result: Option<Value> = None;

            for line in stdout.lines() {
                if line.starts_with("#") {
                    // New result block
                    if let Some(res) = current_result.take() {
                        results.push(res);
                    }
                    let parts: Vec<&str> = line.splitn(3, ' ').collect();
                    if parts.len() >= 3 {
                        let score_str = parts[1].trim_start_matches("(score: ").trim_end_matches(")");
                        if let Ok(score) = score_str.parse::<f64>() {
                            current_result = Some(json!({
                                "score": score,
                                "name": parts[2].trim(),
                            }));
                        }
                    }
                } else if line.trim().starts_with("operation-dbus/") {
                    // Location line
                    if let Some(res) = current_result.as_mut() {
                        let loc_parts: Vec<&str> = line.trim().split(':').collect();
                        if loc_parts.len() >= 4 {
                            res["repo"] = json!(loc_parts[0]);
                            res["file_path"] = json!(loc_parts[1]);
                            let line_range: Vec<&str> = loc_parts[2].split('-').collect();
                            if line_range.len() == 2 {
                                if let (Ok(start), Ok(end)) = (line_range[0].parse::<u64>(), line_range[1].parse::<u64>()) {
                                    res["line_start"] = json!(start);
                                    res["line_end"] = json!(end);
                                }
                            }
                        }
                    }
                } else if line.trim().starts_with("pub ") || line.trim().starts_with("impl ") || line.trim().starts_with("```") || line.trim().starts_with("struct ") {
                    // Content preview - simple heuristic
                    if let Some(res) = current_result.as_mut() {
                        let current_content = res["content_preview"].as_str().unwrap_or("").to_string();
                        res["content_preview"] = json!(format!("{}{}\n", current_content, line.trim()));
                    }
                }
            }
            if let Some(res) = current_result.take() {
                results.push(res);
            }

            Ok(json!(results))
        } else {
            let stderr = String::from_utf8_lossy(&output.stderr).to_string();
            error!("OpenClaw search failed: {}", stderr);
            Err(anyhow!("OpenClaw search failed: {}", stderr))
        }
    }

    fn security_level(&self) -> SecurityLevel {
        SecurityLevel::ReadOnly
    }

    fn category(&self) -> &str {
        "code_search"
    }

    fn tags(&self) -> Vec<String> {
        vec!["openclaw".to_string(), "indexer".to_string(), "code".to_string(), "semantic_search".to_string()]
    }
}

pub fn create_indexer_tools() -> Vec<Arc<dyn Tool>> {
    vec![
        Arc::new(IndexerSearchTool),
    ]
}

//! NonNet database - OVSDB-like interface for non-network plugin state
//!
//! Provides a read-only, OVSDB-compatible JSON-RPC interface over Unix socket
//! for querying non-network plugin state.

use anyhow::{Context, Result};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::{broadcast, RwLock};
use tracing::{debug, info, warn};

use crate::protocol::{error_codes, JsonRpcRequest, JsonRpcResponse};

const NONNET_DB_NAME: &str = "OpNonNet";

/// NonNet update event
#[derive(Debug, Clone)]
pub struct NonNetUpdate {
    pub db_name: String,
    pub table: String,
    pub rows: Vec<Value>,
}

/// NonNet changed event for watch() method
#[derive(Debug, Clone)]
pub struct NonNetChanged {
    pub key: String,
    pub operation: NonNetOperation,
}

/// NonNet operation type
#[derive(Debug, Clone)]
pub enum NonNetOperation {
    Insert,
    Update,
    Delete,
}

/// NonNet database state
pub struct NonNetDb {
    state: Arc<RwLock<NonNetState>>,
    update_tx: broadcast::Sender<NonNetUpdate>,
    /// Broadcast sender for watch() method
    watch_tx: broadcast::Sender<NonNetChanged>,
}

/// Internal state structure
struct NonNetState {
    tables: HashMap<String, Vec<Value>>,
    schema: Value,
}

fn empty_nonnet_schema() -> Value {
    json!({
        "name": NONNET_DB_NAME,
        "tables": {}
    })
}

impl Default for NonNetState {
    fn default() -> Self {
        Self {
            tables: HashMap::new(),
            schema: empty_nonnet_schema(),
        }
    }
}

impl NonNetDb {
    /// Create a new NonNet database
    pub fn new() -> Self {
        let (update_tx, _) = broadcast::channel(100);
        let (watch_tx, _) = broadcast::channel(100);
        Self {
            state: Arc::new(RwLock::new(NonNetState::default())),
            update_tx,
            watch_tx,
        }
    }

    /// Subscribe to database updates
    pub fn subscribe(&self) -> broadcast::Receiver<NonNetUpdate> {
        self.update_tx.subscribe()
    }

    /// Watch for database changes
    pub fn watch(&self) -> broadcast::Receiver<NonNetChanged> {
        self.watch_tx.subscribe()
    }

    /// Set the tables/schema from plugin state
    pub async fn load_from_plugins(&self, plugins: &HashMap<String, Value>) {
        let mut state = self.state.write().await;

        // Build schema and tables from plugin state
        let mut schema_tables = simd_json::value::owned::Object::new();
        let mut tables = HashMap::new();

        for (name, value) in plugins {
            // Skip network plugin
            if name == "net" {
                continue;
            }

            // Infer columns from the value structure
            let columns = infer_columns(value);
            schema_tables.insert(name.clone(), json!({"columns": columns}));

            // Convert value to rows
            let rows = value_to_rows(value);
            tables.insert(name.clone(), rows.clone());

            // Broadcast initial load as update
            let _ = self.update_tx.send(NonNetUpdate {
                db_name: NONNET_DB_NAME.to_string(),
                table: name.clone(),
                rows: rows.clone(),
            });

            // Fire watch broadcast
            let _ = self.watch_tx.send(NonNetChanged {
                key: name.clone(),
                operation: NonNetOperation::Insert,
            });
        }

        state.schema = json!({
            "name": NONNET_DB_NAME,
            "tables": Value::Object(Box::new(schema_tables))
        });
        state.tables = tables;

        debug!("NonNet DB loaded {} tables", state.tables.len());
    }

    /// Update a specific table
    pub async fn update_table(&self, name: &str, rows: Vec<Value>) {
        let mut state = self.state.write().await;
        state.tables.insert(name.to_string(), rows.clone());

        // Keep schema in sync with updated rows.
        let mut schema_tables = simd_json::value::owned::Object::new();
        for (table_name, table_rows) in state.tables.iter() {
            let columns = infer_columns(&Value::Array(table_rows.clone()));
            schema_tables.insert(table_name.clone(), json!({"columns": columns}));
        }
        state.schema = json!({
            "name": NONNET_DB_NAME,
            "tables": Value::Object(Box::new(schema_tables))
        });

        let _ = self.update_tx.send(NonNetUpdate {
            db_name: NONNET_DB_NAME.to_string(),
            table: name.to_string(),
            rows: rows.clone(),
        });

        // Fire watch broadcast
        let _ = self.watch_tx.send(NonNetChanged {
            key: name.to_string(),
            operation: NonNetOperation::Update,
        });
    }

    /// Insert a new table with rows
    pub async fn insert_table(&self, name: &str, rows: Vec<Value>) {
        let mut state = self.state.write().await;
        state.tables.insert(name.to_string(), rows.clone());

        // Update schema
        let mut schema_tables = simd_json::value::owned::Object::new();
        for (table_name, table_rows) in state.tables.iter() {
            let columns = infer_columns(&Value::Array(table_rows.clone()));
            schema_tables.insert(table_name.clone(), json!({"columns": columns}));
        }
        state.schema = json!({
            "name": NONNET_DB_NAME,
            "tables": Value::Object(Box::new(schema_tables))
        });

        let _ = self.update_tx.send(NonNetUpdate {
            db_name: NONNET_DB_NAME.to_string(),
            table: name.to_string(),
            rows: rows.clone(),
        });

        // Fire watch broadcast
        let _ = self.watch_tx.send(NonNetChanged {
            key: name.to_string(),
            operation: NonNetOperation::Insert,
        });
    }

    /// Delete a table
    pub async fn delete_table(&self, name: &str) {
        let mut state = self.state.write().await;
        state.tables.remove(name);

        // Update schema
        let mut schema_tables = simd_json::value::owned::Object::new();
        for (table_name, table_rows) in state.tables.iter() {
            let columns = infer_columns(&Value::Array(table_rows.clone()));
            schema_tables.insert(table_name.clone(), json!({"columns": columns}));
        }
        state.schema = json!({
            "name": NONNET_DB_NAME,
            "tables": Value::Object(Box::new(schema_tables))
        });

        let _ = self.update_tx.send(NonNetUpdate {
            db_name: NONNET_DB_NAME.to_string(),
            table: name.to_string(),
            rows: vec![],
        });

        // Fire watch broadcast
        let _ = self.watch_tx.send(NonNetChanged {
            key: name.to_string(),
            operation: NonNetOperation::Delete,
        });
    }

    /// Run the JSON-RPC server on a Unix socket
    pub async fn run_server(&self, socket_path: &str) -> Result<()> {
        let path = Path::new(socket_path);

        // Create parent directory if needed
        if let Some(dir) = path.parent() {
            tokio::fs::create_dir_all(dir).await.ok();
        }

        // Remove existing socket
        if path.exists() {
            tokio::fs::remove_file(path).await.ok();
        }

        let listener = UnixListener::bind(path).context("Failed to bind NonNet socket")?;

        info!("NonNet JSON-RPC server listening on {}", socket_path);

        loop {
            let (stream, _) = listener.accept().await?;
            let state = Arc::clone(&self.state);

            tokio::spawn(async move {
                if let Err(e) = handle_connection(state, stream).await {
                    warn!("NonNet connection error: {}", e);
                }
            });
        }
    }

    /// Handle a single JSON-RPC request
    pub async fn handle_request(&self, request: JsonRpcRequest) -> JsonRpcResponse {
        let state = self.state.read().await;
        handle_method(&state, request)
    }
}

impl Default for NonNetDb {
    fn default() -> Self {
        Self::new()
    }
}

/// Handle a client connection
async fn handle_connection(state: Arc<RwLock<NonNetState>>, stream: UnixStream) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    while reader.read_line(&mut line).await? > 0 {
        let response = match unsafe { simd_json::from_str::<Value>(line.as_mut_str()) } {
            Ok(value) => {
                let state = state.read().await;
                match simd_json::serde::from_owned_value::<JsonRpcRequest>(value.clone()) {
                    Ok(request) => handle_method(&state, request),
                    Err(e) => JsonRpcResponse::error(
                        value.get("id").cloned().unwrap_or(Value::null()),
                        error_codes::INVALID_REQUEST,
                        format!("Invalid request: {}", e),
                    ),
                }
            }
            Err(e) => JsonRpcResponse::error(
                Value::null(),
                error_codes::PARSE_ERROR,
                format!("Parse error: {}", e),
            ),
        };

        let response_str = simd_json::to_string(&response)?;
        writer.write_all(response_str.as_bytes()).await?;
        writer.write_all(b"\n").await?;

        line.clear();
    }

    Ok(())
}

/// Handle a JSON-RPC method call
fn handle_method(state: &NonNetState, request: JsonRpcRequest) -> JsonRpcResponse {
    let result = match request.method.as_str() {
        "list_dbs" => json!([NONNET_DB_NAME]),

        "get_schema" => {
            let db = request
                .params
                .as_array()
                .and_then(|params| params.first())
                .and_then(|v| v.as_str())
                .unwrap_or(NONNET_DB_NAME);

            if db != NONNET_DB_NAME {
                return JsonRpcResponse::error(
                    request.id,
                    error_codes::NOT_FOUND,
                    format!("Unknown database: {}", db),
                );
            }

            state.schema.clone()
        }

        "transact" => {
            // params: [db, ops...]
            let params = request.params.as_array();
            if let Some(params) = params {
                if params.is_empty() {
                    return JsonRpcResponse::error(
                        request.id,
                        error_codes::INVALID_PARAMS,
                        "Missing database name",
                    );
                }

                let db = params[0].as_str().unwrap_or("");
                if db != NONNET_DB_NAME {
                    return JsonRpcResponse::error(
                        request.id,
                        error_codes::NOT_FOUND,
                        format!("Unknown database: {}", db),
                    );
                }

                // Process operations
                let ops = &params[1..];
                let mut results = Vec::new();

                for op in ops {
                    let op_type = op.get("op").and_then(|v| v.as_str()).unwrap_or("");

                    match op_type {
                        "select" => {
                            let table = op.get("table").and_then(|v| v.as_str()).unwrap_or("");
                            let rows = state.tables.get(table).cloned().unwrap_or_default();
                            results.push(json!({"rows": rows}));
                        }
                        "insert" | "update" | "delete" | "mutate" => {
                            // Read-only database
                            results.push(json!({"error": "Read-only database"}));
                        }
                        _ => {
                            results
                                .push(json!({"error": format!("Unknown operation: {}", op_type)}));
                        }
                    }
                }

                json!(results)
            } else {
                json!({"error": "Invalid params"})
            }
        }

        "echo" => request.params.clone(),

        _ => {
            return JsonRpcResponse::error(
                request.id,
                error_codes::METHOD_NOT_FOUND,
                format!("Unknown method: {}", request.method),
            );
        }
    };

    JsonRpcResponse::success(request.id, result)
}

/// Infer column types from a value
fn infer_columns(value: &Value) -> Value {
    match value {
        Value::Object(map) => {
            let mut cols = simd_json::value::owned::Object::new();
            for (k, v) in map.iter() {
                cols.insert(k.clone(), json!({"type": infer_type(v)}));
            }
            Value::Object(Box::new(cols))
        }
        Value::Array(arr) => {
            if let Some(first) = arr.first() {
                infer_columns(first)
            } else {
                json!({})
            }
        }
        _ => json!({"value": {"type": infer_type(value)}}),
    }
}

/// Infer the type of a value
fn infer_type(value: &Value) -> &'static str {
    if value.is_null() {
        return "null";
    }
    if value.is_bool() {
        return "boolean";
    }
    if value.is_number() {
        return "integer";
    }
    if value.is_str() {
        return "string";
    }
    if value.is_array() {
        return "set";
    }
    if value.is_object() {
        return "map";
    }
    "unknown"
}

/// Convert a value to table rows
fn value_to_rows(value: &Value) -> Vec<Value> {
    match value {
        Value::Array(arr) => arr.clone(),
        Value::Object(map) => {
            // Check if there's an array field
            for (_, v) in map.iter() {
                if let Value::Array(arr) = v {
                    return arr.clone();
                }
            }
            // Return single row
            vec![value.clone()]
        }
        _ => vec![value.clone()],
    }
}

